#!/bin/bash
# make_boards.sh : N report boards. S = m2+h48a+M_SlightArch (start), BO = brow only (m2+h48a+M_Fine), NO = nose only (n1+h48a), HO = hair only (m2+h49a), C = n1+h49a+M_Fine.
set -u; cd "/c/Users/berat/OneDrive/Documents/Unreal Projects/ActionAdventureMovementS"; PY="/c/Program Files/Epic Games/UE_5.8/Engine/Binaries/ThirdParty/Python3/Win64/python.exe"; LB=Tools/CharacterLookdev_20260930/lk_board.py
N="$(cygpath -w "$(pwd)/Saved/Codex/GD11_HeadRefinementN_20261005")"; TR="$(cygpath -w "$(pwd)/Saved/Codex/CharacterIdentity_20260930/track")"; B="$N\\public_report\\boards"; PV="$N\\pv"; CL="$N\\pv\\clay"; CR="$N\\pv\\crop"; PN="$N\\pv\\panel"; FR="$N\\frames"
pt() { "$PY" -c "import json; d=json.load(open('Saved/Codex/GD11_HeadRefinementN_20261005/prov/$1.json')); print(d['read_at'][11:16])" 2>/dev/null || echo "--:--"; }
S=g11rnS; SL="S m2+h48a+SlightArch prov $(pt g11rnS)"; BO=g11rnBO; BL="BO m2+h48a+M_Fine prov $(pt g11rnBO)"; NO=g11rnNO; NL="NO n1+h48a prov $(pt g11rnNO)"; HO=g11rnHO; HL="HO m2+h49a prov $(pt g11rnHO)"; C=g11rnC; CLB="C n1+h49a+M_Fine prov $(pt g11rnC)"
V5="front q3L q3R profL profR"; row() { p=$1; l=$2; out=""; for v in $V5; do out="$out${p}_${v}_custom.png|$v - $l, "; done; echo "${out%, }"; }
"$PY" $LB "$B\\01_WHOLE_HEAD.jpg" "GD11 N - 01 whole head: original reference (row 1) | start m2+h48a (row 2) | new candidate n1+h49a+M_Fine (row 3). Front, two 3/4, two profiles; same cameras, studio light, neutral rig" 500 "$TR\\ref_front_x4.png|reference front (Tier A), $TR\\ref_close_x2.png|reference 3/4 (Tier A), $FR\\g11rn1_real_F.png|n1 in the reference front frame, $FR\\g11rn1_real_C.png|n1 in the reference 3/4 frame, $FR\\g11rn1_ovF.png|n1 50% overlay on reference" "$(row $S "$SL")" "$(row $C "$CLB")"
"$PY" $LB "$B\\02_BROW.jpg" "GD11 N - 02 brow on the SAME m2 + h48a: A current M_SlightArch | B hidden (diagnosis) | C library alternatives; chosen = M_Fine. Row 1 front close (balanced light), row 2 3/4 (studio), row 3 reference crops + whole face" 500 "$CR\\brow_M_SlightArch_front.png|A current M_SlightArch, $CR\\brow_nobrow_front.png|B brow hidden, $CR\\brow_M_Fine_front.png|C chosen M_Fine, $CR\\brow_M_Natural_front.png|M_Natural, $CR\\brow_Soft_front.png|Soft, $CR\\brow_S_FlatThin_front.png|S_FlatThin" "$CR\\brow_M_SlightArch_q3.png|A 3/4, $CR\\brow_nobrow_q3.png|B hidden 3/4, $CR\\brow_M_Fine_q3.png|C M_Fine 3/4, $CR\\brow_M_Natural_q3.png|M_Natural 3/4, $CR\\brow_Soft_q3.png|Soft 3/4, $CR\\brow_S_FlatThin_q3.png|S_FlatThin 3/4" "$CR\\ref_front_brows.png|reference brows front, $CR\\ref_close_brows.png|reference brows 3/4, g11rnBROW_M_SlightArch_front_front_custom.png|A whole face, g11rnBROW_M_Fine_front_front_custom.png|C whole face, g11rnBROW_M_SlightArch_studio_noseroot_custom.png|A nose root, g11rnBROW_M_Fine_studio_noseroot_custom.png|C nose root"
"$PY" $LB "$B\\03_NOSE.jpg" "GD11 N - 03 nose: start m2 vs n1 (same h48a, same brow). Front, 3/4, profile; base / nostrils / upper lip preservation (clay from below + heat); reference nose crops" 520 "g11rnSfc_studio_fcfront_custom.png|m2 front - $SL, g11rnNOfc_studio_fcfront_custom.png|n1 front - $NL, g11rnSfc_studio_fcq3_custom.png|m2 3/4, g11rnNOfc_studio_fcq3_custom.png|n1 3/4, g11rnSfc_studio_fcprofR_custom.png|m2 profile, g11rnNOfc_studio_fcprofR_custom.png|n1 profile" "g11rnSfc_studio_noseroot_custom.png|m2 nose root, g11rnNOfc_studio_noseroot_custom.png|n1 nose root, g11rnSfc_grazing_noseroot_custom.png|m2 grazing, g11rnNOfc_grazing_noseroot_custom.png|n1 grazing, g11rnSfc_studio_lips_custom.png|m2 lips-base, g11rnNOfc_studio_lips_custom.png|n1 lips-base" "$CR\\ref_front_nose.png|reference nose front, $CR\\ref_close_nose.png|reference nose 3/4, $CL\\head_M2_low3q.png|m2 clay from below, $CL\\head_N1_low3q.png|n1 clay from below, $PV\\heat_N1_q3R.png|n1 vs m2 heat (0..1.5 mm), $PV\\nose_profile.png|midline profile m2 (white) vs n1 (orange): identical"
"$PY" $LB "$B\\04_MAIN_HAIR_FLOW.jpg" "GD11 N - 04 main hair flow with the LOOSE groom HIDDEN (only the main mass): h48a vs h49a on m2; row 3: strand-geometry groups (loose families hidden) and edited main guides" 500 "g11rnSmo_mo_q3R_custom.png|h48a main only 3/4 R, g11rnHOmo_mo_q3R_custom.png|h49a main only 3/4 R, g11rnSmo_mo_profR_custom.png|h48a main only profile R, g11rnHOmo_mo_profR_custom.png|h49a main only profile R, g11rnSmo_mo_front_custom.png|h48a main only front, g11rnHOmo_mo_front_custom.png|h49a main only front" "g11rnSmo_mo_q3L_custom.png|h48a main only 3/4 L, g11rnHOmo_mo_q3L_custom.png|h49a main only 3/4 L, g11rnSmo_mo_profL_custom.png|h48a main only profile L, g11rnHOmo_mo_profL_custom.png|h49a main only profile L, g11rnSmo_mo_profR_lit_custom.png|h48a main rear light, g11rnHOmo_mo_profR_lit_custom.png|h49a main rear light" "$PN\\g_h48a_q3R_hidden.png|h48a main groups (geometry), $PN\\g_h49a_q3R_hidden.png|h49a main groups, $PN\\g_h48a_profR_hidden.png|h48a profile, $PN\\g_h49a_profR_hidden.png|h49a profile, $PV\\guides_h49a_sideR.png|edited main guides (h49a; h48a ghost), $PV\\guides_h49a_front3qR.png|edited main guides 3/4"
"$PY" $LB "$B\\05_NAPE_EAR_BUN.jpg" "GD11 N - 05 nape / behind-ear / bun: back, two rear 3/4, two profiles; main only (loose hidden) vs full; h48a vs h49a on m2" 480 "g11rnSmo_mo_back_custom.png|h48a main back, g11rnHOmo_mo_back_custom.png|h49a main back, g11rnSmo_mo_rear3qR_custom.png|h48a main rear 3/4 R, g11rnHOmo_mo_rear3qR_custom.png|h49a main rear 3/4 R, g11rnSmo_mo_rear3qL_custom.png|h48a main rear 3/4 L, g11rnHOmo_mo_rear3qL_custom.png|h49a main rear 3/4 L" "${S}_back_custom.png|h48a full back, ${HO}_back_custom.png|h49a full back, ${S}_rear3qR_lit_custom.png|h48a full rear 3/4 lit, ${HO}_rear3qR_lit_custom.png|h49a full rear 3/4 lit, ${S}_rear3qL_lit_custom.png|h48a full rear 3/4 L lit, ${HO}_rear3qL_lit_custom.png|h49a full rear 3/4 L lit" "${S}_profR_lit_custom.png|h48a profile R lit, ${HO}_profR_lit_custom.png|h49a profile R lit, ${S}_profL_lit_custom.png|h48a profile L lit, ${HO}_profL_lit_custom.png|h49a profile L lit, ${S}_earR_lit_custom.png|h48a ear R, ${HO}_earR_lit_custom.png|h49a ear R" "$PN\\g_h48a_back_nape.png|h48a nape field geometry, $PN\\g_h49a_back_nape.png|h49a nape field (edited spines), $PN\\g_h48a_rear3qR_hidden.png|h48a main rear 3/4 geometry, $PN\\g_h49a_rear3qR_hidden.png|h49a main rear 3/4 geometry, ${S}_cuRear3qR_s_custom.png|h48a nape close, ${HO}_cuRear3qR_s_custom.png|h49a nape close"
"$PY" $LB "$B\\06_SEPARATION_TECH.jpg" "GD11 N - 06 separation (front / 3-4 R): start | brow only | nose only | hair only | combined; sky (gameplay-like) light start vs combined; rig / motion / pitch / after restart / LOD" 440 "${S}_front_custom.png|start - $SL, ${BO}_front_custom.png|brow only - $BL, ${NO}_front_custom.png|nose only - $NL, ${HO}_front_custom.png|hair only - $HL, ${C}_front_custom.png|combined - $CLB, ${S}_q3R_custom.png|start 3/4, ${BO}_q3R_custom.png|brow only 3/4, ${C}_q3R_custom.png|combined 3/4" "g11rnSsky_sky_front_custom.png|start sky light, g11rnCsky_sky_front_custom.png|combined sky light, g11rnSsky_sky_q3R_custom.png|start sky 3/4, g11rnCsky_sky_q3R_custom.png|combined sky 3/4, g11rnSsky_sky_fcq3_custom.png|start sky face, g11rnCsky_sky_fcq3_custom.png|combined sky face, g11rnSsky_sky_rear3qR_custom.png|start sky rear, g11rnCsky_sky_rear3qR_custom.png|combined sky rear" "g11rnrig_blink_3q_custom.png|blink, g11rnrig_smile_3q_custom.png|smile, g11rnrig_jaw_open_3q_custom.png|jaw open, g11rnrig_brows_up_3q_custom.png|brows up, g11rnrig_nostril_dilate_front_custom.png|nostril dilate, g11rnmot_turnL06_back_custom.png|turn L, g11rnP_pitchDn_side_custom.png|pitch down, g11rnafter_rear3qR_custom.png|after restart" "$PN\\lod_f_125.png|front 1.25 m, $PN\\lod_f_300.png|3 m, $PN\\lod_f_600.png|6 m, $PN\\lod_f_1200.png|12 m, $PN\\lod_f_2500.png|25 m, $PN\\lod_d_600.png|45 deg 6 m, $PN\\lod_b_300.png|back 3 m, g11rnmot_stop06_q3_custom.png|stop"
ls -la "Saved/Codex/GD11_HeadRefinementN_20261005/public_report/boards"
